		initial.setQueryExecutionPolicy(QueryExecutionPolicy.of(experimental));
		QueryEvaluationStep step = initial.forWorker(source).precompileRuntimeSubtree(reference.clone(), context);
		int opened = source.opened;
		List<BindingSet> actual = new ArrayList<>();
